//! Build script for `beads_rust`.
//!
//! Uses vergen-gix for stable build/rustc metadata and quiet git probes for
//! optional repository metadata.

use std::{env, path::PathBuf, process::Command};
use vergen_gix::{BuildBuilder, CargoBuilder, Emitter, RustcBuilder};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // The `web` feature embeds `src/web/static/` via rust-embed, but that
    // directory is generated by `scripts/build-web.sh` (requires Node) and is
    // gitignored — so a fresh clone has no such directory and the rust-embed
    // derive fails to compile. Emit a minimal placeholder `index.html` when
    // the real assets are absent so plain `cargo build` / `cargo install` /
    // `install.sh --from-source` work with zero Node dependency. Real assets,
    // once built, always take precedence and are never overwritten.
    if std::env::var("CARGO_FEATURE_WEB").is_ok() {
        ensure_web_static_placeholder();
    }

    let build = BuildBuilder::default().build_timestamp(true).build()?;
    let cargo = CargoBuilder::default().target_triple(true).build()?;
    let rustc = RustcBuilder::default().semver(true).build()?;

    let mut emitter = Emitter::default();
    emitter
        .add_instructions(&build)?
        .add_instructions(&cargo)?
        .add_instructions(&rustc)?;

    emitter.emit()?;
    emit_git_metadata();

    Ok(())
}

/// Ensure `src/web/static/` exists with at least a placeholder `index.html`
/// so the rust-embed derive in `src/web/assets.rs` can compile on a fresh
/// clone. Does nothing when real assets (or a previously emitted placeholder)
/// are already present.
fn ensure_web_static_placeholder() {
    let manifest_dir = match env::var("CARGO_MANIFEST_DIR") {
        Ok(dir) => PathBuf::from(dir),
        Err(_) => return,
    };
    let static_dir = manifest_dir.join("src/web/static");
    let index = static_dir.join("index.html");

    if index.exists() {
        return;
    }

    println!("cargo:warning=Web UI assets not built (src/web/static/index.html missing).");
    println!("cargo:warning=Emitting a placeholder page so the build succeeds without Node.");
    println!("cargo:warning=Run `bash scripts/build-web.sh` to build the real web UI.");

    if let Err(err) = std::fs::create_dir_all(&static_dir) {
        println!(
            "cargo:warning=Could not create {}: {err}",
            static_dir.display()
        );
        return;
    }

    let placeholder = "<!doctype html>\n\
<html lang=\"en\">\n\
<head>\n\
  <meta charset=\"utf-8\">\n\
  <title>br web UI not built</title>\n\
</head>\n\
<body>\n\
  <h1>br web UI not built</h1>\n\
  <p>The embedded web assets were not generated for this build.</p>\n\
  <p>Run <code>bash scripts/build-web.sh</code> (requires Node.js) and rebuild\n\
     to serve the full UI, or use the <code>br</code> CLI / TUI instead.</p>\n\
</body>\n\
</html>\n";

    if let Err(err) = std::fs::write(&index, placeholder) {
        println!("cargo:warning=Could not write {}: {err}", index.display());
    }
}

fn emit_git_metadata() {
    if git_output(&["rev-parse", "--is-inside-work-tree"]).as_deref() == Some("true")
        && let Some(sha) = git_output(&["rev-parse", "HEAD"])
    {
        emit_env("VERGEN_GIT_SHA", &sha);

        if let Some(branch) = git_output(&["rev-parse", "--abbrev-ref", "HEAD"]) {
            emit_env("VERGEN_GIT_BRANCH", &branch);
        }

        if let Some(timestamp) = git_output(&["log", "-1", "--format=%cI"]) {
            emit_env("VERGEN_GIT_COMMIT_TIMESTAMP", &timestamp);
        }

        if let Some(status) = git_output(&["status", "--porcelain"]) {
            emit_env(
                "VERGEN_GIT_DIRTY",
                if status.is_empty() { "false" } else { "true" },
            );
        }
        return;
    }

    if let Some(sha) = first_env(&[
        "VERGEN_GIT_SHA",
        "RCH_SOURCE_COMMIT",
        "RCH_GIT_SHA",
        "RCH_GIT_COMMIT",
        "GIT_COMMIT",
        "GITHUB_SHA",
        "CI_COMMIT_SHA",
        "BUILDKITE_COMMIT",
        "DRONE_COMMIT_SHA",
        "VERCEL_GIT_COMMIT_SHA",
    ]) {
        emit_env("VERGEN_GIT_SHA", &sha);
    }

    if let Some(branch) = first_env(&["VERGEN_GIT_BRANCH", "GITHUB_REF_NAME", "CI_COMMIT_REF_NAME"])
    {
        emit_env("VERGEN_GIT_BRANCH", &branch);
    }
}

fn emit_env(key: &str, value: &str) {
    println!("cargo:rustc-env={key}={value}");
}

fn git_output(args: &[&str]) -> Option<String> {
    let output = Command::new("git").args(args).output().ok()?;

    if !output.status.success() {
        return None;
    }

    let value = String::from_utf8(output.stdout).ok()?;
    let trimmed = value.trim();

    Some(trimmed.to_string())
}

fn first_env(names: &[&str]) -> Option<String> {
    for name in names {
        println!("cargo:rerun-if-env-changed={name}");
        if let Ok(value) = env::var(name) {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
    }

    None
}
